/* Story language */
.reader-tools { display:flex; align-items:center; gap:12px; flex-wrap:wrap; justify-content:flex-end; }
.language-picker { display:inline-flex; align-items:center; gap:14px; font-size:12px; color:var(--muted); }
.language-picker span { white-space:nowrap; }
.language-picker select { font:inherit; color:var(--ink); background:#fffdf8; border:1px solid var(--line); border-radius:8px; min-height:42px; max-width:100%; padding:10px 32px 10px 14px; }
.language-picker select:disabled { opacity:.6; }
.chat-card .language-picker { display:flex; justify-content:flex-end; margin-bottom:12px; }
@media(max-width:480px) { .reader-tools { width:100%; justify-content:flex-start; } .language-picker { width:100%; flex-direction:column; align-items:stretch; gap:6px; } .language-picker select { width:100%; } }

/* Read-along highlighting */

"use client";
import { LANGUAGES, type LanguageCode } from "@/lib/languages";

export default function LanguagePicker({ value, onChange, disabled }: { value: LanguageCode; onChange: (code: LanguageCode) => void; disabled?: boolean }) {
  return <label className="language-picker">
    <span>Story language</span>
    <select value={value} disabled={disabled} onChange={e => onChange(e.target.value as LanguageCode)}>
      {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.native === l.name ? l.name : `${l.native} · ${l.name}`}</option>)}
    </select>
  </label>;
}

